UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 67, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 68, 7, NULL::text),(3, 196, 51, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 251, 1295, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='6c681497-3d5e-5c9a-874e-0c7d8546278f' AND md5(a.contenido)='93442f5c0d27b7324c36029da949837c' RETURNING a.id,md5(a.contenido) hash;